import React, { useState, useEffect, useCallback } from 'react';
import ViewNotices from '../components/ViewNotices';
import NoticeSearch from '../components/NoticeSearch';
import NoticeFilter from '../components/NoticeFilter';
import * as noticeService from '../services/noticeService';

const PublicNoticeBoard = () => {
  const [notices, setNotices] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({ category: null, department: null, priority: null, keyword: '' });

  const loadNotices = useCallback(async () => {
    setLoading(true);
    try {
      let data;
      if (filters.keyword || filters.category || filters.department || filters.priority) {
        data = await noticeService.searchNotices({
          keyword: filters.keyword || undefined,
          categoryId: filters.category || undefined,
          departmentId: filters.department || undefined,
          size: 50,
        });
      } else {
        data = await noticeService.getPublicNotices({ size: 50 });
      }

      let list = data && data.content ? data.content : [];
      if (filters.priority) {
        list = list.filter((n) => n.priority === filters.priority);
      }
      setNotices(list);
    } catch (e) {
      setNotices([]);
    } finally {
      setLoading(false);
    }
  }, [filters]);

  useEffect(() => {
    loadNotices();
  }, [loadNotices]);

  const handleSearch = (keyword) => {
    setFilters((prev) => ({ ...prev, keyword }));
  };

  const handleFilterChange = (filterValues) => {
    setFilters((prev) => ({ ...prev, ...filterValues }));
  };

  return (
    <div>
      {/* Hero Welcome */}
      <div
        style={{
          background: 'linear-gradient(135deg, #1e1b4b, #312e81, #4338ca)',
          color: 'white',
          padding: '2.5rem 2rem',
          borderRadius: 'var(--radius-lg)',
          marginBottom: '2rem',
          boxShadow: 'var(--shadow-lg)',
        }}
      >
        <div style={{ maxWidth: '750px' }}>
          <span className="badge" style={{ backgroundColor: 'rgba(255, 255, 255, 0.2)', color: '#ffffff', marginBottom: '0.75rem' }}>
            Official Circulars & Bulletin
          </span>
          <h1 style={{ color: '#ffffff', fontSize: '2.2rem', marginBottom: '0.75rem' }}>
            School Notice & Bulletin Board
          </h1>
          <p style={{ color: '#c7d2fe', fontSize: '1.05rem', lineHeight: '1.6' }}>
            Explore verified official school announcements, examination timetables, academic calendars, and departmental events in real-time.
          </p>
        </div>
      </div>

      {/* Search & Filters */}
      <div style={{ marginBottom: '1.5rem' }}>
        <NoticeSearch onSearch={handleSearch} />
      </div>

      <NoticeFilter onFilterChange={handleFilterChange} />

      {/* Notices List */}
      <div>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
          <h2 style={{ fontSize: '1.35rem' }}>Published Notices ({notices.length})</h2>
        </div>

        {loading ? (
          <div style={{ textAlign: 'center', padding: '3rem' }}>
            <p style={{ color: 'var(--text-muted)' }}>Loading notices...</p>
          </div>
        ) : (
          <ViewNotices customNotices={notices} />
        )}
      </div>
    </div>
  );
};

export default PublicNoticeBoard;
